"""Report rendering: Markdown, HTML (single file, no external assets) and JSON."""

from __future__ import annotations

import html
import json
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Sequence

from .models import CATEGORY_LABELS, Finding, ScanResult, Severity, Status, sort_findings

STATUS_ICON = {
    Status.PASS: "✅",
    Status.FAIL: "❌",
    Status.WARN: "⚠️",
    Status.INFO: "ℹ️",
    Status.SKIP: "⏭️",
    Status.ERROR: "❗",
}
DISCLAIMER = (
    "Generated by homeguard. Use it only for devices and networks you own or are authorized to test. "
    "Results come from read-only checks and public vulnerability data and may contain false positives or "
    "false negatives; use your own judgment."
)
TITLE = "homeguard security self-audit report"


def _by_category(findings: Sequence[Finding]) -> Dict[str, List[Finding]]:
    out: Dict[str, List[Finding]] = {}
    for f in sort_findings(list(findings)):
        out.setdefault(f.category, []).append(f)
    return out


def _md_cell(text: str) -> str:
    return (text or "").replace("|", "\\|").replace("\n", "<br>")


def _scopes(result: ScanResult) -> str:
    return ", ".join(CATEGORY_LABELS.get(c, c) for c in result.scopes)


# ---------------------------------------------------------------- Markdown


def render_markdown(result: ScanResult) -> str:
    s = result.summary()
    lines = [
        f"# {TITLE}",
        "",
        f"- Generated: {result.finished_at or result.started_at}",
        f"- Host: {result.hostname} ({result.platform})",
        f"- Scope: {_scopes(result)}",
        f"- Tool version: homeguard {result.tool_version}",
        "",
        f"> {DISCLAIMER}",
        "",
        "## Summary",
        "",
        "| Critical | High | Medium | Low | Info | Passed | Errors |",
        "|---:|---:|---:|---:|---:|---:|---:|",
        f"| {s['critical']} | {s['high']} | {s['medium']} | {s['low']} | {s['info']} | {s['passed']} | {s['errors']} |",
        "",
    ]
    problems = result.problems()
    lines += ["## Fix first", ""]
    if problems:
        for i, f in enumerate(problems, 1):
            lines.append(f"{i}. **[{f.severity.label}] {f.title}** - {f.target}")
            if f.remediation:
                lines.append(f"   - Fix: {f.remediation}")
    else:
        lines.append("Nothing needs fixing. 🎉")
    lines.append("")

    if result.authorization:
        lines += ["## Scan authorization", "", "| Target | Method | Time |", "|---|---|---|"]
        for a in result.authorization:
            lines.append(f"| {a['target']} | {a['method']} | {a['time']} |")
        lines += ["", f"Statement: {result.authorization[0]['statement']}", ""]

    for cat, items in _by_category(result.findings).items():
        lines += [f"## {CATEGORY_LABELS.get(cat, cat)}", ""]
        if cat == "network" and result.hosts:
            lines += ["### Live devices", "", "| IP | Host name | MAC | Open ports |", "|---|---|---|---|"]
            for h in result.hosts:
                ports = ", ".join(str(p) for p in sorted(h.open_ports)) or "-"
                lines.append(f"| {h.ip} | {_md_cell(h.hostname) or '-'} | {h.mac or '-'} | {ports} |")
            lines += ["", "### Results", ""]
        lines += ["| Status | Severity | Check | Target | Detail |", "|---|---|---|---|---|"]
        for f in items:
            lines.append(
                f"| {STATUS_ICON[f.status]} {f.status.label} | {f.severity.label} | {_md_cell(f.title)} | "
                f"{_md_cell(f.target)} | {_md_cell(f.detail)} |"
            )
        lines.append("")
        details = [f for f in items if f.is_problem or f.status == Status.ERROR]
        if details:
            lines += ["### Details and fixes", ""]
            for f in details:
                lines.append(f"#### {STATUS_ICON[f.status]} {f.title}")
                lines.append("")
                lines.append(f"- Target: {f.target}")
                lines.append(f"- Severity: {f.severity.label} (`{f.check_id}`)")
                if f.detail:
                    lines.append(f"- Detail: {f.detail}")
                if f.remediation:
                    lines.append(f"- Fix: {f.remediation}")
                if f.evidence:
                    lines.append(f"- Evidence: `{f.evidence.splitlines()[0][:200].replace('`', chr(39))}`")
                for ref in f.references:
                    lines.append(f"- Reference: <{ref}>")
                lines.append("")
    for note in result.notes:
        lines.append(f"> Note: {note}")
    return "\n".join(lines).rstrip() + "\n"


# ---------------------------------------------------------------- HTML

