def _e(x: object) -> str:
    return html.escape(str(x or ""), quote=True)


def _sev_badge(sev: Severity) -> str:
    return f'<span class="sev sev-{sev.value}">{_e(sev.label)}</span>'


def render_html(result: ScanResult) -> str:
    s = result.summary()
    h: List[str] = [
        '<!doctype html><html lang="en"><head><meta charset="utf-8">',
        '<meta name="viewport" content="width=device-width,initial-scale=1">',
        f"<title>{_e(TITLE)}</title><style>{_CSS}</style></head><body><main>",
        f"<h1>{_e(TITLE)}</h1>",
        f'<div class="meta">Generated {_e(result.finished_at or result.started_at)} · Host {_e(result.hostname)}'
        f" ({_e(result.platform)}) · homeguard {_e(result.tool_version)} · Scope: {_e(_scopes(result))}</div>",
        f'<div class="disclaimer">{_e(DISCLAIMER)}</div>',
        '<h2>Summary</h2><div class="cards">',
    ]
    for key, label, color in [
        ("critical", "Critical", "critical"),
        ("high", "High", "high"),
        ("medium", "Medium", "medium"),
        ("low", "Low", "low"),
        ("passed", "Passed", "pass"),
        ("errors", "Errors", "info"),
    ]:
        h.append(f'<div class="card"><b style="color:var(--{color})">{s[key]}</b><span>{label}</span></div>')
    h.append("</div><h2>Fix first</h2>")
    problems = result.problems()
    if problems:
        h.append("<ol>")
        for f in problems:
            h.append(
                f"<li>{_sev_badge(f.severity)} <b>{_e(f.title)}</b> - {_e(f.target)}"
                + (f'<div class="fix">Fix: {_e(f.remediation)}</div>' if f.remediation else "")
                + "</li>"
            )
        h.append("</ol>")
    else:
        h.append("<p>Nothing needs fixing. 🎉</p>")

    if result.authorization:
        h.append(
            '<h2>Scan authorization</h2><div class="tbl"><table><tr><th>Target</th><th>Method</th><th>Time</th></tr>'
        )
        for a in result.authorization:
            h.append(f"<tr><td>{_e(a['target'])}</td><td>{_e(a['method'])}</td><td>{_e(a['time'])}</td></tr>")
        h.append(f'</table></div><p class="meta">Statement: {_e(result.authorization[0]["statement"])}</p>')

    for cat, items in _by_category(result.findings).items():
        h.append(f"<h2>{_e(CATEGORY_LABELS.get(cat, cat))}</h2>")
        if cat == "network" and result.hosts:
            h.append(
                '<h3>Live devices</h3><div class="tbl"><table>'
                "<tr><th>IP</th><th>Host name</th><th>MAC</th><th>Open ports</th></tr>"
            )
            for host in result.hosts:
                ports = ", ".join(
                    f"{p}" + (f" <code>{_e(b[:60])}</code>" if b else "")
                    for p, b in sorted(host.open_ports.items())
                )
                h.append(
                    f"<tr><td>{_e(host.ip)}</td><td>{_e(host.hostname) or '-'}</td><td>{_e(host.mac) or '-'}</td>"
                    f"<td>{ports or '-'}</td></tr>"
                )
            h.append("</table></div><h3>Results</h3>")
        h.append(
            '<div class="tbl"><table><tr><th>Status</th><th>Severity</th><th>Check</th><th>Target</th><th>Detail</th></tr>'
        )
        for f in items:
            h.append(
                f'<tr><td class="st">{STATUS_ICON[f.status]} {_e(f.status.label)}</td><td>{_sev_badge(f.severity)}</td>'
                f"<td>{_e(f.title)}</td><td>{_e(f.target)}</td><td>{_e(f.detail)}</td></tr>"
            )
        h.append("</table></div>")
        for f in items:
            if not (f.is_problem or f.status == Status.ERROR):
                continue
            h.append(f"<details><summary>{STATUS_ICON[f.status]} {_e(f.title)} - {_e(f.target)}</summary>")
            h.append(f"<p>{_sev_badge(f.severity)} <code>{_e(f.check_id)}</code></p>")
            if f.detail:
                h.append(f"<p><b>Detail:</b> {_e(f.detail)}</p>")
            if f.remediation:
                h.append(f"<p><b>Fix:</b> {_e(f.remediation)}</p>")
            if f.evidence:
                h.append(f"<pre>{_e(f.evidence)}</pre>")
            for ref in f.references:
                if ref.startswith(("https://", "http://")):
                    h.append(
                        f'<p><a href="{_e(ref)}" rel="noopener noreferrer" target="_blank">{_e(ref)}</a></p>'
                    )
            h.append("</details>")
    for note in result.notes:
        h.append(f'<p class="meta">Note: {_e(note)}</p>')
    h.append("</main></body></html>")
    return "\n".join(h)


def render_json(result: ScanResult) -> str:
    return json.dumps(result.to_dict(), ensure_ascii=False, indent=2)


RENDERERS = {"md": (render_markdown, "md"), "html": (render_html, "html"), "json": (render_json, "json")}


def write_reports(result: ScanResult, output_dir: str, formats: Sequence[str]) -> List[Path]:
    out = Path(output_dir).expanduser()
    out.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    paths = []
    for fmt in formats:
        if fmt not in RENDERERS:
            raise ValueError(f"Unsupported report format: {fmt} (choose from md, html, json)")
        fn, ext = RENDERERS[fmt]
        p = out / f"homeguard-report-{stamp}.{ext}"
        p.write_text(fn(result), encoding="utf-8")
        paths.append(p)
    return paths
